std::size_t mask = ckh->nbuckets - 1;
std::size_t i = hash & mask;
std::size_t j = (hash ^ (hash >> 12)) & mask;

ckh_bucket_t *b = &ckh->buckets[i];
if (b->key != nullptr && ckh->keycmp(b->key, searchkey, ckh->keycmp_arg)) {
    *key = b->key;
    *data = b->data;
    return false;
}
b = &ckh->buckets[j];
if (b->key != nullptr && ckh->keycmp(b->key, searchkey, ckh->keycmp_arg)) {
    *key = b->key;
    *data = b->data;
    return false;
}
return true;

